import React, { useState, useContext } from "react";
import "./MyAccount.css";
import { AuthContext } from "../../Context/AuthContext";
import { updateProfile, changePassword /*, uploadAvatar*/ } from "../../Services/ApiUserService";

const EMAIL_RGX = /^\S+@\S+\.\S+$/;
const PHONE_RGX = /^[0-9()+\-.\s]{9,20}$/;

const MyAccount = () => {
    const { user } = useContext(AuthContext);

    const [form, setForm] = useState({
        firstName: user?.name || "",
        lastName: user?.surname || "",
        accountName: user?.accountname || "",
        email: user?.email || "",
        phone: user?.phone || "",
        currentPassword: "",
        newPassword: "",
        confirmPassword: "",
    });

    const [errors, setErrors] = useState({});
    const [saving, setSaving] = useState(false);
    const [alert, setAlert] = useState({ type: "", msg: "" }); // 'success' | 'danger' | ''

    const onChange = (e) =>
        setForm((s) => ({ ...s, [e.target.name]: e.target.value }));

    const validate = () => {
        const err = {};
        if (!form.firstName.trim()) err.firstName = "Vui lòng nhập Tên.";
        if (!form.lastName.trim()) err.lastName = "Vui lòng nhập Họ.";
        if (!form.accountName.trim()) err.accountName = "Vui lòng nhập Tên tài khoản.";
        if (!EMAIL_RGX.test(form.email.trim())) err.email = "Email không hợp lệ.";
        if (!PHONE_RGX.test(form.phone.trim())) err.phone = "Số điện thoại không hợp lệ.";

        // Nếu bất kỳ ô mật khẩu nào được nhập → kiểm tra đủ bộ và khớp
        const anyPw = form.currentPassword || form.newPassword || form.confirmPassword;
        if (anyPw) {
            if (!form.currentPassword) err.currentPassword = "Nhập mật khẩu hiện tại.";
            if (!form.newPassword) err.newPassword = "Nhập mật khẩu mới.";
            if (!form.confirmPassword) err.confirmPassword = "Xác nhận mật khẩu mới.";
            if (form.newPassword && form.newPassword.length < 8)
                err.newPassword = "Mật khẩu mới tối thiểu 8 ký tự.";
            if (form.newPassword && form.confirmPassword && form.newPassword !== form.confirmPassword)
                err.confirmPassword = "Xác nhận mật khẩu mới không khớp.";
        }

        setErrors(err);
        return Object.keys(err).length === 0;
    };

    const onSubmit = async (e) => {
        e.preventDefault();
        setAlert({ type: "", msg: "" });

        if (!validate()) return;

        setSaving(true);
        try {
            // 1) Cập nhật hồ sơ cơ bản (đúng theo payload bạn đang dùng)
            await updateProfile({
                name: form.firstName.trim(),
                surname: form.lastName.trim(),
                phone: form.phone.trim(),
                // Nếu backend cho phép cập nhật thêm thì bổ sung:
                // accountname: form.accountName.trim(),
                // email: form.email.trim(),
            });

            // 2) Nếu nhập mật khẩu → gọi đổi mật khẩu
            if (form.currentPassword && form.newPassword && form.confirmPassword) {
                await changePassword({
                    currentPassword: form.currentPassword,
                    newPassword: form.newPassword,
                    confirmPassword: form.confirmPassword, // giữ theo API bạn đang gọi
                });
                // dọn trường mật khẩu sau khi đổi
                setForm((s) => ({
                    ...s,
                    currentPassword: "",
                    newPassword: "",
                    confirmPassword: "",
                }));
            }

            setAlert({ type: "success", msg: "Cập nhật thành công!" });
        } catch (error) {
            console.error("Update error:", error);
            setAlert({
                type: "danger",
                msg: error?.message || "Có lỗi xảy ra khi lưu thay đổi.",
            });
        } finally {
            setSaving(false);
        }
    };

    const fc = (name) =>
        `form-control form-control-elevated ${errors[name] ? "is-invalid" : ""}`;

    return (
        <div className="account-wrap py-4">
            <div className="container">
                <form className="mx-auto account-card p-4 p-md-5" onSubmit={onSubmit} noValidate>
                    {!!alert.type && (
                        <div className={`alert alert-${alert.type} mb-4`} role="alert">
                            {alert.msg}
                        </div>
                    )}

                    <div className="row g-4">
                        <div className="col-md-6">
                            <label className="form-label required">Tên</label>
                            <input
                                className={fc("firstName")}
                                name="firstName"
                                value={form.firstName}
                                onChange={onChange}
                                required
                            />
                            {errors.firstName && <div className="invalid-feedback">{errors.firstName}</div>}
                        </div>

                        <div className="col-md-6">
                            <label className="form-label required">Họ</label>
                            <input
                                className={fc("lastName")}
                                name="lastName"
                                value={form.lastName}
                                onChange={onChange}
                                required
                            />
                            {errors.lastName && <div className="invalid-feedback">{errors.lastName}</div>}
                        </div>

                        <div className="col-12">
                            <label className="form-label required">Tên Tài khoản</label>
                            <input
                                className={fc("accountName")}
                                name="accountName"
                                value={form.accountName}
                                onChange={onChange}
                                required
                            />
                            {errors.accountName && <div className="invalid-feedback">{errors.accountName}</div>}
                            <div className="form-text fst-italic mt-1">
                                Tên này sẽ hiển thị trong trang Tài khoản và phần Đánh giá Tài khoản
                            </div>
                        </div>

                        <div className="col-12">
                            <label className="form-label required">Địa chỉ email</label>
                            <input
                                type="email"
                                className={fc("email")}
                                name="email"
                                value={form.email}
                                onChange={onChange}
                                required
                            />
                            {errors.email && <div className="invalid-feedback">{errors.email}</div>}
                        </div>

                        <div className="col-12">
                            <label className="form-label required">Số điện thoại</label>
                            <input
                                type="tel"
                                className={fc("phone")}
                                name="phone"
                                value={form.phone}
                                onChange={onChange}
                                required
                            />
                            {errors.phone && <div className="invalid-feedback">{errors.phone}</div>}
                        </div>

                        <div className="col-12">
                            <hr className="my-4" />
                            <div className="section-title text-uppercase fw-semibold text-muted">
                                Thay đổi mật khẩu
                            </div>
                        </div>

                        <div className="col-12">
                            <label className="form-label">
                                Mật khẩu hiện tại <span className="text-muted">(bỏ trống nếu không đổi)</span>
                            </label>
                            <input
                                type="password"
                                className={fc("currentPassword")}
                                name="currentPassword"
                                value={form.currentPassword}
                                onChange={onChange}
                            />
                            {errors.currentPassword && (
                                <div className="invalid-feedback">{errors.currentPassword}</div>
                            )}
                        </div>

                        <div className="col-12">
                            <label className="form-label">
                                Mật khẩu mới <span className="text-muted">(bỏ trống nếu không đổi)</span>
                            </label>
                            <input
                                type="password"
                                className={fc("newPassword")}
                                name="newPassword"
                                value={form.newPassword}
                                onChange={onChange}
                            />
                            {errors.newPassword && <div className="invalid-feedback">{errors.newPassword}</div>}
                        </div>

                        <div className="col-12">
                            <label className="form-label">Xác nhận mật khẩu mới</label>
                            <input
                                type="password"
                                className={fc("confirmPassword")}
                                name="confirmPassword"
                                value={form.confirmPassword}
                                onChange={onChange}
                            />
                            {errors.confirmPassword && (
                                <div className="invalid-feedback">{errors.confirmPassword}</div>
                            )}
                        </div>

                        <div className="col-12">
                            <button type="submit" className="btn btn-save px-4 fw-semibold" disabled={saving}>
                                {saving ? "Đang lưu..." : "Lưu thay đổi"}
                            </button>
                        </div>
                    </div>
                </form>
            </div>
        </div>
    );
};

export default MyAccount;
